def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 90:
                    aggressive_count += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    high_need = hp <= 3 or no_water_days >= 2
    medium_need = hp <= 5 or no_water_days >= 1
    scarce = slots <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if high_need:
        if highest_prev >= 120:
            bid = 122.0
        elif highest_prev >= 90:
            bid = highest_prev + 2.0
        else:
            bid = 96.0 if scarce else 82.0
    elif medium_need:
        if scarce:
            if highest_prev >= 115:
                bid = 58.0
            elif highest_prev >= 80:
                bid = highest_prev + 1.5
            else:
                bid = 74.0
        else:
            if aggressive_count >= 2:
                bid = 28.0
            else:
                bid = max(36.0, avg_prev * 0.72)
    else:
        if scarce:
            if desperate_count >= 2 or highest_prev >= 100:
                bid = 16.0
            elif highest_prev >= 75:
                bid = 52.0
            else:
                bid = 44.0
        else:
            if aggressive_count >= 1:
                bid = 12.0
            else:
                bid = 24.0

    if day >= 8:
        if hp >= 6 and no_water_days == 0:
            bid *= 0.8
        elif hp <= 4:
            bid *= 1.1

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.92)
    else:
        bid = min(bid, budget * 0.75)

    if high_need:
        bid = max(bid, min(budget, 45.0))

    if bid < 0:
        bid = 0.0

    return float(min(budget, round(bid, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Collect yesterday's bids from traces
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday = max(yesterday_bids) if yesterday_bids else None

    # Determine base bid based on supply and yesterday's pressure
    if supply <= 16:
        if max_yesterday and max_yesterday >= 120:
            # They are aggressive, try to outbid slightly
            base = max_yesterday + 2
        else:
            base = DAILY_SALARY * 0.85
    elif supply <= 19:
        if max_yesterday and max_yesterday >= 100:
            base = min(DAILY_SALARY * 0.75, max_yesterday + 1)
        else:
            base = DAILY_SALARY * 0.6
    else:
        if max_yesterday and max_yesterday >= 100:
            base = DAILY_SALARY * 0.4
        else:
            base = DAILY_SALARY * 0.3

    # Adjust for HP
    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 5 and supply <= 16:
        base = max(base, DAILY_SALARY * 0.8)

    # Ensure not negative and within budget
    bid = max(0, min(budget, base))
    return bid

